[{"location":"api/#API-Reference","page":"API Reference","title":"API Reference","text":"","category":"section"},{"location":"api/#Types","page":"API Reference","title":"Types","text":"","category":"section"},{"location":"api/#Factory-Functions","page":"API Reference","title":"Factory Functions","text":"","category":"section"},{"location":"api/#Geometry","page":"API Reference","title":"Geometry","text":"","category":"section"},{"location":"api/#Layout","page":"API Reference","title":"Layout","text":"","category":"section"},{"location":"api/#Paths","page":"API Reference","title":"Paths","text":"","category":"section"},{"location":"api/#Transformation-Methods","page":"API Reference","title":"Transformation Methods","text":"","category":"section"},{"location":"api/#Geometry-Analysis","page":"API Reference","title":"Geometry Analysis","text":"","category":"section"},{"location":"api/#Boolean-and-Clipper-Operations","page":"API Reference","title":"Boolean & Clipper Operations","text":"","category":"section"},{"location":"api/#I/O-Functions","page":"API Reference","title":"I/O Functions","text":"","category":"section"},{"location":"api/#Other-Functions","page":"API Reference","title":"Other Functions","text":"","category":"section"},{"location":"#Gdstk.jl","page":"Home","title":"Gdstk.jl","text":"Gdstk.jl is a high-performance Julia wrapper for the gdstk C++ library. It provides a fast and efficient way to create, read, and manipulate GDSII and OASIS layout files.","category":"section"},{"location":"#Features","page":"Home","title":"Features","text":"Fast Layout Generation: Create complex geometries using optimized C++ primitives.\nHierarchical Design: Support for Cells and References to build modular layouts.\nBoolean Operations: High-performance polygon clipping and merging via the Clipper library.\nFlexible Paths: FlexPath and RobustPath for advanced routing.\nGDSII/OASIS Support: Robust I/O for industry-standard formats.","category":"section"},{"location":"#Installation","page":"Home","title":"Installation","text":"using Pkg\nPkg.add(\"Gdstk\")","category":"section"},{"location":"#Quick-Start","page":"Home","title":"Quick Start","text":"using Gdstk\n\n# Create a library\nlib = new_library(\"MyLibrary\", 1e-6, 1e-9)\n\n# Create a cell\ncell = new_cell(\"Main\")\nadd_cell!(lib, cell)\n\n# Create a rectangle\nrect = rectangle(0, 0, 10, 10, 1, 0)\nadd_polygon!(cell, rect)\n\n# Write to GDS\nwrite_gds(lib, \"output.gds\", 0)","category":"section"},{"location":"#Table-of-Contents","page":"Home","title":"Table of Contents","text":"Pages = [\"api.md\"]","category":"section"}]
